package com.aaliyun.leadnews.search.web;import com.aaliyun.leadnews.common.context.UserContext;import com.aaliyun.leadnews.common.exception.BusinessException;import com.aaliyun.leadnews.search.service.SearchRebuildService;import org.springframework.web.bind.annotation.*;import java.util.Map;@RestController @RequestMapping("/internal/search")public class InternalSearchController{private final SearchRebuildService rebuild;public InternalSearchController(SearchRebuildService r){rebuild=r;}@PostMapping("/rebuild")public Map<String,Long>rebuild()throws Exception{if(!UserContext.isInternal())throw new BusinessException(40300,"Internal access required");return Map.of("indexed",rebuild.rebuild());}}
